package com.paytrace.ledger;import org.junit.jupiter.api.*;import java.math.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class DoubleEntryLedgerTest {@Test void rejectsUnbalancedJournal(){var transaction=org.mockito.Mockito.mock(LedgerTransactionRepository.class);var entries=org.mockito.Mockito.mock(LedgerEntryRepository.class);var ledger=new DoubleEntryLedger(transaction,entries);assertThatThrownBy(()->ledger.post(UUID.randomUUID(),"bad",List.of(new DoubleEntryLedger.LedgerLine("BANK",EntryDirection.DEBIT,new BigDecimal("10"),"INR")))).isInstanceOf(DoubleEntryLedger.LedgerImbalanceException.class);}}
